def find_path(maze, x, y, path):
    if not valid(maze, x, y):
        return False
    if maze[x][y] == 'G':
        path.append((x, y))
        return True
    maze[x][y] = 'V'
    for dx, dy in [(0,1), (1,0), (0,-1), (-1,0)]:
        if find_path(maze, x+dx, y+dy, path):
            path.append((x, y))
            return True
    return False
```

